// Phase 13 analytics report builders (item AD) — same reportRows pattern
// as registers.go / mis_registers.go, so these inherit the existing
// workbook envelope (report name, period, generated date, generated by,
// filters, record count, totals) rather than defining a second one.
//
// Every builder delegates to internal/analytics, so an exported workbook
// carries exactly the figures the corresponding dashboard shows.
package reporting

import (
	"strconv"
	"time"

	"github.com/santosh0921/nbfc-backend/internal/analytics"
	"github.com/santosh0921/nbfc-backend/internal/database"
	"github.com/santosh0921/nbfc-backend/internal/models"
)

func pctStr(p *float64) string {
	if p == nil {
		// Item C: never render an infinite or fabricated percentage.
		return analytics.NoComparableBase
	}
	return strconv.FormatFloat(*p, 'f', 2, 64)
}

func f2(v float64) string { return strconv.FormatFloat(v, 'f', 2, 64) }

// metricRows flattens a metric group into the shared growth-workbook shape.
func metricRows(groups ...[]analytics.Metric) [][]string {
	var rows [][]string
	for _, g := range groups {
		for _, m := range g {
			rows = append(rows, []string{
				m.Key, m.Label, m.Unit, f2(m.Current), f2(m.Prior), pctStr(m.ChangePercent),
			})
		}
	}
	return rows
}

var growthHeaders = []string{"KPI Key", "Metric", "Unit", "Current Period", "Prior Period", "Change %"}

func buildGrowthDashboardReport(from, to time.Time) *reportRows {
	d := analytics.GenerateGrowthDashboard(from, to)
	rows := metricRows(d.Customers, d.Applications, d.Loans, d.Disbursements,
		d.Collections, d.Portfolio, d.Revenue, d.Expenses, d.Profitability)
	return &reportRows{Headers: growthHeaders, Rows: rows, Totals: map[string]string{
		"Prior Period From": d.PriorFrom.Format(time.RFC3339),
		"Prior Period To":   d.PriorTo.Format(time.RFC3339),
		"Record Count":      itoaInt(len(rows)),
		"Note":              "Collections include principal recovery and are NOT revenue. Revenue is recognized income from the general ledger.",
	}}
}

// The individually-named growth workbooks item AD lists are the same
// calculation scoped to one metric group — sharing the builder keeps
// them from ever disagreeing with the combined dashboard.
func growthSlice(from, to time.Time, pick func(analytics.GrowthDashboard) []analytics.Metric) *reportRows {
	d := analytics.GenerateGrowthDashboard(from, to)
	rows := metricRows(pick(d))
	return &reportRows{Headers: growthHeaders, Rows: rows, Totals: map[string]string{
		"Prior Period From": d.PriorFrom.Format(time.RFC3339),
		"Prior Period To":   d.PriorTo.Format(time.RFC3339),
		"Record Count":      itoaInt(len(rows)),
	}}
}

func buildProductAnalyticsReport(from, to time.Time) *reportRows {
	r := analytics.ProductAnalytics(from, to)
	return dimensionRows(r)
}

func buildSegmentAnalyticsReport(from, to time.Time) *reportRows {
	return dimensionRows(analytics.SegmentAnalytics(from, to))
}

func buildGeographicAnalyticsReport(from, to time.Time) *reportRows {
	return dimensionRows(analytics.GeographicAnalytics(from, to))
}

func dimensionRows(r analytics.DimensionReport) *reportRows {
	headers := []string{"Value", "Customers", "Applications", "Approved", "Disbursed Count",
		"Disbursed (paise)", "Approval Rate %", "Avg Loan Size (paise)", "Delinquency Rate %"}
	var rows [][]string
	var totalDisbursed int64
	for _, x := range r.Rows {
		rows = append(rows, []string{
			x.Value, itoa64(x.Customers), itoa64(x.Applications), itoa64(x.Approved),
			itoa64(x.Disbursed), itoa64(x.DisbursedPaise), f2(x.ApprovalRatePercent),
			f2(x.AverageLoanSizePaise), f2(x.DelinquencyRatePercent),
		})
		totalDisbursed += x.DisbursedPaise
	}
	totals := map[string]string{
		"Dimension":               r.Dimension,
		"Total Disbursed (paise)": itoa64(totalDisbursed),
		"Record Count":            itoaInt(len(rows)),
	}
	// Unavailable dimensions are carried into the workbook itself so an
	// exported file never looks like a complete picture when it isn't.
	for i, u := range r.Unavailable {
		totals["Not Available "+strconv.Itoa(i+1)] = u
	}
	return &reportRows{Headers: headers, Rows: rows, Totals: totals}
}

func buildDPDAnalyticsReport(_, to time.Time) *reportRows {
	r := analytics.GenerateDPDTrend(to, 6)
	headers := []string{"Period From", "Period To", "Bucket", "Accounts", "Amount (paise)", "Portfolio %"}
	var rows [][]string
	for _, p := range r.Periods {
		for _, b := range p.Buckets {
			rows = append(rows, []string{
				p.PeriodFrom.Format("2006-01-02"), p.PeriodTo.Format("2006-01-02"),
				b.Bucket, itoa64(b.Accounts), itoa64(b.AmountPaise), f2(b.PortfolioPercent),
			})
		}
	}
	return &reportRows{Headers: headers, Rows: rows, Totals: map[string]string{
		"Trend":        r.Trend,
		"Methodology":  r.Methodology,
		"Disclaimer":   r.Disclaimer,
		"Record Count": itoaInt(len(rows)),
	}}
}

func buildConcentrationReport(_, to time.Time) *reportRows {
	r := analytics.GenerateConcentration(to)
	headers := []string{"Dimension", "Label", "Exposure (paise)", "Portfolio %"}
	var rows [][]string
	add := func(dim string, entries []analytics.ConcentrationEntry) {
		for _, e := range entries {
			rows = append(rows, []string{dim, e.Label, itoa64(e.ExposurePaise), f2(e.PortfolioPercent)})
		}
	}
	add("Top Borrowers", r.TopBorrowers)
	add("Top Products", r.TopProducts)
	add("Top States", r.TopStates)
	return &reportRows{Headers: headers, Rows: rows, Totals: map[string]string{
		"Total Portfolio (paise)": itoa64(r.TotalPortfolioPaise),
		"Indicator":               r.Indicator,
		"Record Count":            itoaInt(len(rows)),
	}}
}

func buildCollectionPerformanceReport(from, to time.Time) *reportRows {
	r := analytics.GenerateCollectionRisk(from, to)
	headers := []string{"Measure", "Value"}
	rows := [][]string{
		{"Due (paise)", itoa64(r.DuePaise)},
		{"Collected (paise)", itoa64(r.CollectedPaise)},
		{"Overdue (paise)", itoa64(r.OverduePaise)},
		{"Collection Rate %", f2(r.CollectionRatePercent)},
		{"Overdue Rate %", f2(r.OverdueRatePercent)},
		{"Repeat Overdue Customers", itoa64(r.RepeatOverdueCustomers)},
		{"Trend", r.Trend},
	}
	return &reportRows{Headers: headers, Rows: rows, Totals: map[string]string{
		"Disclaimer":   r.Disclaimer,
		"Record Count": itoaInt(len(rows)),
	}}
}

func buildRiskSignalsReport(from, to time.Time) *reportRows {
	var signals []models.RiskSignal
	database.DB.Where("observed_at BETWEEN ? AND ?", from, to).Order("observed_at DESC").Find(&signals)
	headers := []string{"Signal ID", "Type", "Severity", "Subject Type", "Subject Ref", "Reason", "Source", "Status", "Reviewed By", "Observed At"}
	var rows [][]string
	for _, s := range signals {
		rows = append(rows, []string{
			itoa(s.ID), s.SignalType, s.Severity, s.SubjectType, s.SubjectRef,
			s.Reason, s.Source, s.Status, s.ReviewedBy, s.ObservedAt.Format(time.RFC3339),
		})
	}
	return &reportRows{Headers: headers, Rows: rows, Totals: map[string]string{
		"Record Count": itoaInt(len(rows)),
		"Note":         "These are review signals only. Nothing in this report is a finding of fraud or misconduct.",
	}}
}

func buildManagementAlertsReport(from, to time.Time) *reportRows {
	var alerts []models.ManagementAlert
	database.DB.Where("created_at BETWEEN ? AND ?", from, to).Order("created_at DESC").Find(&alerts)
	headers := []string{"Alert ID", "Metric", "Current Value", "Threshold", "Direction", "Severity", "Explanation", "Source", "Status", "Owner", "Created At"}
	var rows [][]string
	for _, a := range alerts {
		rows = append(rows, []string{
			itoa(a.ID), a.MetricKey, f2(a.CurrentValue), f2(a.ThresholdValue),
			a.Direction, a.Severity, a.Explanation, a.Source, a.Status, a.Owner,
			a.CreatedAt.Format(time.RFC3339),
		})
	}
	return &reportRows{Headers: headers, Rows: rows, Totals: map[string]string{
		"Record Count": itoaInt(len(rows)),
		"Note":         "An empty report means no management thresholds have been configured, not that no risk exists.",
	}}
}

func buildKPIDictionaryReport(_, _ time.Time) *reportRows {
	kpis := analytics.ListKPIs()
	headers := []string{"Key", "Name", "Definition", "Formula", "Data Source", "Frequency", "Unit",
		"Owner", "Notes", "Dependency", "Lineage", "Last Updated"}
	var rows [][]string
	for _, k := range kpis {
		lineage := k.Lineage.Dashboard + " → " + k.Lineage.Report + " → " + k.Lineage.Calculation +
			" → " + k.Lineage.Source + " → " + k.Lineage.Transaction
		rows = append(rows, []string{
			k.Key, k.Name, k.Definition, k.Formula, k.DataSource, k.Frequency, k.Unit,
			k.Owner, k.Notes, k.Dependency, lineage, k.UpdatedAt.Format(time.RFC3339),
		})
	}
	return &reportRows{Headers: headers, Rows: rows, Totals: map[string]string{"Record Count": itoaInt(len(rows))}}
}

func itoa64(v int64) string { return strconv.FormatInt(v, 10) }

// RegisterReportForTest exposes a built register to tests in other
// packages. reportRows is deliberately unexported — client code must go
// through the export handlers, which apply authorization — so this
// returns a plain, read-only view of the same content rather than
// widening the real type's visibility.
type RegisterReportForTest struct {
	Headers []string
	Rows    [][]string
	Totals  map[string]string
}

func BuildRegisterReportForTest(reportType string, from, to time.Time) (RegisterReportForTest, bool) {
	r, ok := BuildRegisterReport(reportType, from, to)
	if !ok || r == nil {
		return RegisterReportForTest{}, false
	}
	return RegisterReportForTest{Headers: r.Headers, Rows: r.Rows, Totals: r.Totals}, true
}
